const timezone = 'UTC'; // Set an IANA time zone here.
function localDatetime({timezone}) {
  const date = new Date();
  const parts = Object.fromEntries(new Intl.DateTimeFormat('en-GB', {timeZone: timezone, year:'numeric', month:'2-digit', day:'2-digit', hour:'2-digit', minute:'2-digit', second:'2-digit', hourCycle:'h23', timeZoneName:'longOffset'}).formatToParts(date).map(({type,value})=>[type,value]));
  const ms = String(date.getUTCMilliseconds()).padStart(3,'0');
  const offset = parts.timeZoneName === 'GMT' ? '+00:00' : parts.timeZoneName.replace('GMT','');
  return {utc:date.toISOString(),year:+parts.year,month:+parts.month-1,day:+parts.day,hour:+parts.hour,minute:+parts.minute,second:+parts.second,millisecond:+ms,formatted:`${parts.year}-${parts.month}-${parts.day} ${parts.hour}:${parts.minute}:${parts.second}.${ms} ${offset}`};
}

return [{json: localDatetime({timezone})}];
